 class="icon-button" aria-label="Unduh <?= e($name) ?>" href="<?= e(url('dokumen/lihat',['id'=>$id,'unduh'=>1])) ?>"><?= icon('download') ?></a></div><?php endforeach;?><?php if($lamaran['portofolio']):?><p><strong>Portofolio:</strong> <a target="_blank" rel="noopener noreferrer" href="<?= e($lamaran['portofolio']) ?>"><?= e($lamaran['portofolio']) ?> ↗</a></p><?php endif;?><h3>Surat Pengantar</h3><p class="prose"><?= nl2br(e($lamaran['suratPengantar']?:'Tidak ada surat pengantar tambahan.')) ?></p></section><section class="card"><h2>Riwayat Hasil Seleksi</h2><?php if(!$hasil):?><p class="muted">Menunggu peninjauan rekruter.</p><?php endif;?><?php foreach($hasil as $h):?><div class="history-item"><div class="section-heading"><strong><?= e($h['namaTahap']) ?></strong><?= badge($h['hasil']) ?></div><p><?= e($h['catatan']?:'Tidak ada catatan tambahan.') ?></p><small><?= tanggal($h['diperbaruiPada'],'d M Y, H:i') ?> WIB</small></div><?php endforeach;?></section></div>
<aside class="stack"><section class="card"><h2>Jadwal Seleksi</h2><?php if(!$jadwal):?><div class="empty-inline"><?= icon('calendar') ?><p>Belum ada jadwal dari rekruter.</p></div><?php endif;?><?php foreach($jadwal as $j):?><div class="agenda-detail"><span class="badge blue"><?= e($j['namaTahap']) ?></span><h3><?= e($j['judul']) ?></h3><p><?= tanggal($j['waktu'],'d M Y, H:i') ?> WIB</p><p><?= e($j['lokasi']) ?></p><p class="muted"><?= e($j['catatan']) ?></p><?php if($j['tautan']):?><a class="button secondary full" href="<?= e($j['tautan']) ?>" target="_blank" rel="noopener noreferrer">Buka tautan pertemuan ↗</a><?php endif;?></div><?php endforeach;?></section>
<?php if($currentUser['role']!=='Admin'):?><section class="card"><h3>Komunikasi seleksi</h3><?php if($lamaran['administrasiLolos']&&!$lamaran['perusahaanDihapus']):?><p class="muted">Koordinasikan tahap berikutnya melalui percakapan lamaran.</p><a class="button secondary full" href="<?= e(url('chat',['id'=>$lamaran['idLamaran']])) ?>"><?= icon('chat') ?> Buka Percakapan</a><?php else:?><p class="muted">Chat tersedia setelah lolos seleksi administrasi.</p><?php endif;?></section><?php endif;?>
